ALTER TABLE clinic_schedule ADD COLUMN fee_cents INTEGER NOT NULL DEFAULT 0;
CREATE TABLE payment_order (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES tenant(id),user_id BIGINT NOT NULL REFERENCES app_user(id),patient_id BIGINT NOT NULL REFERENCES patient_profile(id),slot_id BIGINT NOT NULL REFERENCES appointment_slot(id),request_key VARCHAR(100) NOT NULL,amount_cents INTEGER NOT NULL,status VARCHAR(30) NOT NULL,expires_at TIMESTAMP NOT NULL,appointment_id BIGINT REFERENCES appointment(id),created_at TIMESTAMP NOT NULL,UNIQUE(tenant_id,user_id,request_key));
CREATE UNIQUE INDEX uq_payment_pending ON payment_order(tenant_id,patient_id,slot_id) WHERE status='PENDING';
CREATE INDEX idx_payment_due ON payment_order(status,expires_at,id);
CREATE TABLE mock_payment_receipt (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES tenant(id),order_id BIGINT NOT NULL UNIQUE REFERENCES payment_order(id),transaction_key VARCHAR(100) NOT NULL UNIQUE,amount_cents INTEGER NOT NULL,refunded BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP NOT NULL);
